# Parse actuators
actuators_info = []
for a in root.iter("general"):
    name = a.get("name")
    if not name:
        continue
    joint = a.get("joint")
    tendon = a.get("tendon")
    binding = joint if joint else f"tendon:{tendon}"
    ctrl_str = a.get("ctrlrange")
    cls = a.get("class", "xarm7")
    if ctrl_str:
        ctrl = [float(x) for x in ctrl_str.split()]
    else:
        ctrl = default_ctrlrange.get(cls, [-6.28319, 6.28319])
    actuators_info.append({"name": name, "joint": binding, "ctrlrange": ctrl})

for a in actuators_info:
    print(a)

# Sites
